// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        vm.prank(0x000000000000000000000000000000000000bEEF, 0x000000000000000000000000000000000000bEEF);
        c = new MultiplicatorX4();
    }

    function _run(address caller) internal {
        vm.assume(caller == c.Owner() || caller == address(this));
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue((caller == c.Owner()) || reverted);
    }

    function testFuzz_run(address caller) public {
        vm.assume(uint160(caller) > 255 && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(caller);
    }

    receive() external payable { }
}
